t=np.array([1,2,5,10,20]);base=np.array([4.7,4.5,4.2,4.3,4.6]);parallel=base+.10;twist=base+.10*(t-5)/5;ax.plot(t,base,color=ACCENT,marker='o',label='Base curve');ax.plot(t,parallel,color=BAD,ls='--',label='Parallel +10 bp');ax.plot(t,twist,color=WARM,ls=':',marker='s',label='Illustrative twist');ax.set_xlabel('Maturity (years)');ax.set_ylabel('Yield (%)');ax.set_title('Curve shape matters beyond parallel duration',loc='left');ax.legend(fontsize=7);ax.grid(alpha=.25)
